## Code Example

```javascript
// Minimal mapping and dedupe for a simple onboarding Saga
const processedEventIds = new Set();
function onEvent(evt) {
  if (processedEventIds.has(evt.id)) return;
  processedEventIds.add(evt.id);
  const cmd = mapEventToCommand(evt);
  publishToOutbox(cmd);
}
function mapEventToCommand(evt) {
  switch (evt.type) {
    case 'UserCreated': return { type: 'GrantCredit', payload: { userId: evt.payload.userId }, correlationId: evt.correlationId };
    case 'CreditGranted': return { type: 'MarkOnboardDone', payload: { userId: evt.payload.userId }, correlationId: evt.correlationId };
    case 'CreditFailed': return { type: 'RollbackUser', payload: { userId: evt.payload.userId }, correlationId: evt.correlationId };
    default: return null;
  }
}
```

